(async function(){while(typeof Gauge=="undefined")await new Promise(r => setTimeout(r, 500));
        const tstamp=1787759516;document.getElementById("qMeterUpdated").innerText=writeAge(tstamp,1);
        const sigmaCombinedMagInPc=7;
        var opts={angle:0.1,lineWidth:0.28,radiusScale:0.96,pointer:{length:0.41,strokeWidth:0.066,color:'#333'},
            limitMax:true,limitMin:true,colorStart:'#273',colorStop:'#a33',strokeColor:'#E0E0E0',
            staticZones:[
                {strokeStyle:"#273", min:-100, max:Math.max(-100,-1.1*sigmaCombinedMagInPc), height:1},
                {strokeStyle:"#eee", min:Math.max(-100,-1.1*sigmaCombinedMagInPc), max:Math.min(100,1.1*sigmaCombinedMagInPc), height:1},
                {strokeStyle:"#bb202a", min:Math.min(100,1.1*sigmaCombinedMagInPc), max:100, height:1}
            ],staticLabels:{font:"16px sans-serif",labels:[-100,-50,0,50,100],color:"#000000",fractionDigits:0},
            generateGradient:true,highDpiSupport:true,
        };
        var target=document.getElementById('gauge-mag');target.classList.remove("waitBg");var gauge=new Gauge(target).setOptions(opts); // create sexy gauge!
        gauge.maxValue=100;gauge.setMinValue(-100);gauge.animationSpeed=5;gauge.set(-8);
        const sigmaNumQuakes=199.7, avgNumQuakes=652.19,actualNum=598;
        let base10=Math.floor(Math.log10(Math.max(2*actualNum,avgNumQuakes+1.5*sigmaNumQuakes)));let maxScale=Math.max(2*avgNumQuakes,5);
        while (maxScale<Math.max(actualNum,avgNumQuakes+1.5*sigmaNumQuakes)) maxScale += 10**base10;
        let labels=[0,10**base10,2*10**base10,5*10**base10,10*10**base10,20*10**base10,30*10**base10,50*10**base10,75*10**base10,100*10**base10,200*10**base10,300*10**base10,500*10**base10,750*10**base10,1000*10**base10];
        if (base10<0) labels=[0,1,2,5,10];
        var opts={
            angle:0.1,lineWidth:0.28,radiusScale:0.96,pointer:{length:0.41, strokeWidth:0.066, color:'#333'},
            limitMax:true,limitMin:true,colorStart:'#273',colorStop:'#a33',strokeColor:'#E0E0E0',
            staticZones:[
                {strokeStyle:"#273", min:0, max:Math.max(0,avgNumQuakes-sigmaNumQuakes), height:1},
                {strokeStyle:"#eee", min:Math.max(0,avgNumQuakes-sigmaNumQuakes), max:avgNumQuakes + sigmaNumQuakes, height:1},
                {strokeStyle:"#bb202a", min:avgNumQuakes+sigmaNumQuakes, max:100000000, height:1}
            ],staticLabels:{font:"16px sans-serif",labels:labels,color:"#000000",fractionDigits:0},
            generateGradient:true,highDpiSupport:true,
        };
        var target=document.getElementById('gauge-quakes');target.classList.remove("waitBg");
        var gauge2=new Gauge(target).setOptions(opts);
        gauge2.setMinValue(0);gauge2.maxValue=maxScale;gauge2.animationSpeed=10;gauge2.set(598);
    })();
